import json, random, subprocess, itertools, sys
sys.path.insert(0,'/workspace/tmp')
import fuzz as base
MAIN=base.MAIN

def gen_obs(rng, doc):
    obs=[]
    qids=[q['id'] for q in doc['queries']]; pids=[p['id'] for p in doc['profiles']]
    if not qids or not pids: return obs
    for i in range(rng.randint(0,10)):
        r=rng.random()
        if r<0.2:
            res={'status':'timeout'}
        else:
            ans=[]
            for _ in range(rng.randint(0,4)):
                t=rng.choice(['A','AAAA','TXT','CNAME'])
                if t=='A': d='192.0.2.%d'%rng.randint(0,255)
                elif t=='AAAA': d=rng.choice(['2001:db8::1','::1','2001:DB8:0:0:0:0:0:2'])
                elif t=='TXT': d=rng.choice(['x','MiXeD',''])
                else: d=rng.choice(['a.test.','OUT.','self.test.','x.y.'])
                ans.append({'owner':rng.choice(['a.test.','A.TEST.','out.','*.test.']),'type':t,'data':d})
            res={'status':'response','rcode':rng.choice(['NOERROR','NXDOMAIN','SERVFAIL','REFUSED']),'answer':ans}
        obs.append({'id':'o%d'%i,'query':rng.choice(qids),'profile':rng.choice(pids),'result':res})
    return obs

def make_doc2(rng):
    doc=base.make_doc(rng)
    # retry-ish enrich profiles/queries
    doc['profiles']=[{'id':'p%d'%i,'max_aliases':rng.randint(0,3),
                      'cname':rng.choice(['follow','stop']),
                      'wildcard':rng.choice(['rfc','off','one-label','rfc'])}
                     for i in range(rng.randint(1,6))]
    # sometimes duplicate settings
    if rng.random()<0.5 and len(doc['profiles'])>1:
        doc['profiles'][-1]={**doc['profiles'][0],'id':doc['profiles'][-1]['id']}
    names=['a.test.','b.test.','x.a.test.','*.test.','self.test.','outside.','p.q.test.','sub.test.','.','c.a.*.a.test.']
    qs=[]
    for i in range(rng.randint(0,9)):
        qs.append({'id':'q%d'%i,'name':rng.choice(names),'type':rng.choice(['A','AAAA','TXT','CNAME']),'cost':rng.randint(1,10)})
    doc['queries']=qs
    doc['observations']=gen_obs(rng,doc)
    return doc

def main():
    rng=random.Random(777)
    tested=0; invalids=0
    for it in range(400):
        doc=make_doc2(rng)
        raw=json.dumps(doc).encode()
        p=subprocess.run(MAIN,input=raw,capture_output=True)
        assert p.returncode==0
        actual=json.loads(p.stdout)
        if 'error' in actual:
            invalids+=1; continue
        try:
            base.check(doc,actual)
        except AssertionError as e:
            print("FAIL iteration",it)
            print(json.dumps(doc,indent=1))
            print("ACTUAL",json.dumps(actual,indent=1))
            print(e)
            return
        tested+=1
    print("ok tested",tested,"invalids",invalids)
main()
